<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('index')}">公共场所防控二维码列表</a>				    <a href="{pigcms{:U('user_list')}" class="on">二维码所有填写记录</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('user_list')}" method="get">							<input type="hidden" name="c" value="PreventionControl"/>							<input type="hidden" name="a" value="user_list"/>							用户电话: 							<input type="text" name="phone" class="input-text" value="{pigcms{$_GET['phone']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="submit" value="查询" class="button"/>							&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;总共收集 {pigcms{$count} 条，今天收集 {pigcms{$today_count} 条						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>用户信息</th>								<th>二维码ID</th>								<th>二维码类别</th>								<th>二维码信息</th>								<th>地点</th>								<th>体温</th>								<th>备注信息</th>								<th>时间</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>											{pigcms{$vo.name}<br/>											{pigcms{$vo.phone}										</td>										<td>{pigcms{$vo.control_id}</td>										<td>{pigcms{$type_info[$vo['type']]}</td>										<td>											{pigcms{$vo.info_name}<br/>											{pigcms{$vo.info_phone}										</td>										<td>											<if condition="$vo['type'] eq 0 || $vo['type'] eq 2">												上车地点：{pigcms{$vo.start_address}<br/>												下车地点：{pigcms{$vo.end_address}											<else/>												{pigcms{$vo.address}											</if>										</td>										<td>											<if condition="$vo['type'] eq 0 || $vo['type'] eq 2">												/											<else/>												{pigcms{$vo.temp}											</if>										</td>										<td>{pigcms{$vo.remark}</td>										<td>											<if condition="$vo['type'] eq 0 || $vo['type'] eq 2">												上车时间：{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<br/>												下车时间：{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}											<else/>												登记时间：{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}											</if>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>